<script setup lang="ts">import{computed,onMounted,reactive,ref,watch}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import http from'../../api/http';import TablePager from'../../shared/components/TablePager.vue';type F={key:string;db:string;label:string;required?:boolean;type?:'date'|'number'};const props=defineProps<{kind:string}>();const cs:any={warehouses:{title:'仓库主数据',fields:[{key:'warehouseCode',db:'warehouse_code',label:'仓库编码',required:true},{key:'warehouseName',db:'warehouse_name',label:'仓库名称',required:true},{key:'factoryCode',db:'factory_code',label:'工厂编码',required:true},{key:'warehouseType',db:'warehouse_type',label:'仓库类型'}]},'work-centers':{title:'工作中心',fields:[{key:'workCenterCode',db:'work_center_code',label:'中心编码',required:true},{key:'workCenterName',db:'work_center_name',label:'中心名称',required:true},{key:'workshopCode',db:'workshop_code',label:'车间编码',required:true},{key:'capacityPerDay',db:'capacity_per_day',label:'日产能',type:'number'}]},'production-versions':{title:'生产版本',fields:[{key:'productionVersionCode',db:'production_version_code',label:'版本编码',required:true},{key:'productCode',db:'product_code',label:'产品编码',required:true},{key:'bomCode',db:'bom_code',label:'BOM编码',required:true},{key:'bomVersion',db:'bom_version',label:'BOM版本',required:true},{key:'routingCode',db:'routing_code',label:'工艺路线',required:true},{key:'routingVersion',db:'routing_version',label:'路线版本',required:true},{key:'factoryCode',db:'factory_code',label:'工厂编码',required:true},{key:'effectiveDate',db:'effective_date',label:'生效日期',required:true,type:'date'}]}};const c=computed(()=>cs[props.kind]),rows=ref<any[]>([]),loading=ref(false),dialog=ref(false),id=ref<number|null>(null),keyword=ref(''),page=ref(1),size=ref(20),total=ref(0),form=reactive<any>({});async function load(){loading.value=true;try{const{data}=await http.get(`/mdm/${props.kind}`,{params:{keyword:keyword.value||undefined,page:page.value,size:size.value}});rows.value=data.data.content;total.value=data.data.totalElements}finally{loading.value=false}}function create(){id.value=null;Object.keys(form).forEach(k=>delete form[k]);c.value.fields.forEach((f:F)=>form[f.key]='');dialog.value=true}function edit(r:any){id.value=r.id;c.value.fields.forEach((f:F)=>form[f.key]=r[f.db]);dialog.value=true}async function save(){const m=c.value.fields.find((f:F)=>f.required&&!form[f.key]);if(m)return ElMessage.warning(`请填写${m.label}`);id.value?await http.put(`/mdm/${props.kind}/${id.value}`,form):await http.post(`/mdm/${props.kind}`,form);ElMessage.success('保存成功');dialog.value=false;await load()}async function disable(r:any){await ElMessageBox.confirm('确认停用？','确认',{type:'warning'});await http.delete(`/mdm/${props.kind}/${r.id}`);await load()}watch(()=>props.kind,()=>{page.value=1;load()});onMounted(load)</script>
<template><section class="page"><div class="head"><div><span>主数据基础资料</span><h1>{{c.title}}</h1><p>由MDM统一维护，下游系统只读消费。</p></div><el-button type="primary" @click="create">新增</el-button></div><el-card shadow="never"><div class="bar"><el-input v-model="keyword" placeholder="编码或名称" @keyup.enter="page=1;load()"/><el-button @click="page=1;load()">查询</el-button></div><el-table :data="rows" v-loading="loading" stripe><el-table-column v-for="f in c.fields" :key="f.db" :prop="f.db" :label="f.label"/><el-table-column prop="status" label="状态"><template #default="{row}">{{$zh(row.status)}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link @click="edit(row)">编辑</el-button><el-button link type="warning" @click="disable(row)">停用</el-button></template></el-table-column></el-table><TablePager v-model:page="page" v-model:size="size" :total="total" @change="load"/></el-card><el-dialog v-model="dialog" :title="c.title" width="720px"><el-form label-position="top"><el-row :gutter="16"><el-col v-for="f in c.fields" :key="f.key" :span="12"><el-form-item :label="f.label" :required="f.required"><el-date-picker v-if="f.type==='date'" v-model="form[f.key]" value-format="YYYY-MM-DD"/><el-input-number v-else-if="f.type==='number'" v-model="form[f.key]"/><el-input v-else v-model="form[f.key]" :disabled="Boolean(id)&&f.key.endsWith('Code')"/></el-form-item></el-col></el-row></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></section></template><style scoped>.page{max-width:1480px;margin:auto}.head{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:17px}.head span{color:#3775d6;font-size:10px}.head h1{margin:6px 0;color:#243d5d}.head p{color:#8291a4;font-size:12px}.bar{display:flex;gap:8px;margin-bottom:14px}.bar .el-input{width:280px}</style>
